package ro.leo.visual;
import ro.leo.i18n.L;
import android.content.*;import android.os.*;import android.provider.Settings;import android.widget.*;import java.util.*;
/** Real battery broadcasts and Android saver; no fabricated remaining-time estimate. */
public final class BatterySettingsActivity extends LeoActivity {
    private boolean charging;private int selected;private final BroadcastReceiver updates=new BroadcastReceiver(){public void onReceive(Context c,Intent i){show();}};
    protected void onResume(){super.onResume();IntentFilter f=new IntentFilter(Intent.ACTION_BATTERY_CHANGED);f.addAction(PowerManager.ACTION_POWER_SAVE_MODE_CHANGED);registerReceiver(updates,f);show();}
    protected void onPause(){unregisterReceiver(updates);super.onPause();}
    private void show(){Intent b=registerReceiver(null,new IntentFilter(Intent.ACTION_BATTERY_CHANGED));if(b!=null)BatterySession.observe(this,b);int level=b==null?0:b.getIntExtra(BatteryManager.EXTRA_LEVEL,0)*100/Math.max(1,b.getIntExtra(BatteryManager.EXTRA_SCALE,100));charging=b!=null&&b.getIntExtra(BatteryManager.EXTRA_PLUGGED,0)!=0;PowerManager power=(PowerManager)getSystemService(POWER_SERVICE);String health=b==null?L.t("Indisponibil"):health(b.getIntExtra(BatteryManager.EXTRA_HEALTH,0));list(L.t("Baterie Leo"),Arrays.asList(L.t("Nivel · ")+level+"% · "+(charging?L.t("Încărcare"):L.t("Pe baterie")),L.t("Economisire · ")+(power.isPowerSaveMode()?L.t("Pornită"):L.t("Oprită"))+(charging?L.t(" · la încărcător"):""),L.t("Temperatură · ")+(b==null?"—":b.getIntExtra(BatteryManager.EXTRA_TEMPERATURE,0)/10f+" °C"),L.t("Tensiune · ")+(b==null?"—":b.getIntExtra(BatteryManager.EXTRA_VOLTAGE,0)+" mV"),L.t("Stare raportată · ")+health,L.t("Ecran și temporizare"),L.t("Diagnostic complet"),BatterySession.text(this)),selected,new Choice(){public void pick(int i){selected=i;if(i==1){options(L.t("Economisire Android"),new String[]{L.t("Oprită"),charging?L.t("Pornire · necesită deconectarea încărcătorului"):L.t("Pornită")},new Choice(){public void pick(int n){if(n==1&&charging){notice(L.t("Economisirea se poate activa după deconectarea încărcătorului"));return;}try{Settings.Global.putInt(getContentResolver(),"low_power",n);show();}catch(RuntimeException e){notice(L.t("Comutator indisponibil"));}}});}else if(i==5)startActivity(new Intent(BatterySettingsActivity.this,DisplaySettingsActivity.class));else if(i==6)startActivity(new Intent(BatterySettingsActivity.this,DiagnosticActivity.class));else if(i==7)options(L.t("Probă de consum"),new String[]{BatterySession.active(BatterySettingsActivity.this)?L.t("Încheie și salvează"):L.t("Începe pe baterie"),L.t("Cum măsor?")},new Choice(){public void pick(int action){if(action==1){notice(L.t("Scoate USB, începe proba, apoi stinge ecranul cel puțin 5 minute. Încheie înainte să reconectezi cablul. Valorile sunt aproximative."));return;}try{if(BatterySession.active(BatterySettingsActivity.this))BatterySession.stop(BatterySettingsActivity.this);else BatterySession.start(BatterySettingsActivity.this);show();}catch(IllegalStateException e){notice(e.getMessage());}}});else notice(L.t("Valoare raportată de driver; fără estimare inventată de autonomie."));}},L.t("Actualiz."),new Runnable(){public void run(){show();}});}
    private static String health(int value){switch(value){case BatteryManager.BATTERY_HEALTH_GOOD:return L.t("Bună");case BatteryManager.BATTERY_HEALTH_OVERHEAT:return L.t("Supraîncălzire");case BatteryManager.BATTERY_HEALTH_COLD:return L.t("Rece");case BatteryManager.BATTERY_HEALTH_DEAD:return L.t("Defectă");case BatteryManager.BATTERY_HEALTH_OVER_VOLTAGE:return L.t("Tensiune mare");default:return L.t("Necunoscută");}}
}
